async () => {
    if (this.pageView) return;
    const defaultViewport = this.pdfPage.getViewport({ scale: 1 });

    const pageView = (this.pageView = new pdfjsViewer.PDFPageView({
      container: this.container,
      id: this.pageNumber,
      scale: defaultViewport.scale,
      defaultViewport,
      eventBus: new pdfjsViewer.EventBus(),
      layerProperties: {
        linkService: this.pdfContext.linkService,
        annotationStorage: this.pdfContext.pdf.annotationStorage,
      },
      enableDetailCanvas: true,
      enableOptimizedPartialRendering: true,
    }));
    if (pageView.pdfPage !== this.pdfPage) {
      this.pdfPage.cleanup();
      pageView.setPdfPage(this.pdfPage);
    }
    const { scale, rotation } = this;
    pageView.update({ scale, rotation });

    this.resize();
    await queueTask(this, this._draw);
    this.scriber.active = true;
  }

async () => {
    ScPDFPage.debug && (this._drawStart = performance.now());
    if (this.pageView?.renderingState === RenderingStates.INITIAL) {
      Object.assign(this.pageView?.draw, { pageNumber: this.pageNumber });
      await this.pageView?.draw();
    }
    if (this.pageView?.renderingState !== RenderingStates.FINISHED) {
      ScPDFPage.debug && console.log('cancelled page ', this.pageNumber, `${performance.now() - this._drawStart  }ms`);
      return;
    }
    ScPDFPage.debug && console.log('done page ', this.pageNumber, `${performance.now() - this._drawStart  }ms`);
    if (this.scriber.dirty) {
      this.scriber.isSleeping = false;
      this.scriber.sync();
    }
    this.emit('sc-page-drawn', {
      detail: { pageNumber: this.pageNumber },
    });
  }

(e: Event) => {
    const { name, value } = (
      e as CustomEvent<{
        name: keyof ToolState;
        value: any;
      }>
    ).detail;
    switch (name) {
      case 'currentPage':
        this.scrollToPage(value);
        break;
      case 'zoomRatio':
        this.scale = value / 100;
        break;
      case 'rotation':
        if (this.fileTool?.resConfig.rotateScope === 'page') {
          const page = this.pages.item(this.fileTool.currentPage - 1);
          if (page)
            page.rotation =
              (page.rotation + (value - this.rotation) + 360) % 360;
        } else {
          this.pages.forEach(page => (page.rotation = value));
        }
        this.rotation = value;
        break;
      default:
        break;
    }
  }

async (e: Event) => {
    if (e.defaultPrevented) return;
    e.preventDefault();
    const { detail } = e as CustomEvent<{
      pageNumber: number;
      provide: (canvas: HTMLCanvasElement) => void;
    }>;

    await this.updateComplete;

    const page = this.shadowRoot?.querySelector<ScPDFPage>(
      `sc-pdf-page[data-page="${detail.pageNumber}"]`
    );
    page?.getThumbnail().then(detail.provide);
  }

(entries: IntersectionObserverEntry[]) => {
    entries.forEach(entry => {
      const page = entry.target;
      if (!(page instanceof ScPDFPage)) return;
      if (entry.isIntersecting) {
        this._pagesInView.add(page.pageNumber);
      } else {
        this._pagesInView.delete(page.pageNumber);
      }
    });
    if (this._pagesInView.size) {
      const pageNumber = Math.min(...this._pagesInView);
      this.fileTool?.setPage(pageNumber, { emit: false });
      this.emit('sc-page-visible', {
        detail: { pageNumber },
        bubbles: true,
        composed: true,
      });
    }
  }

(e: PointerEvent) => {
    const s = this.scale;
    e.preventDefault();

    this.isDrawing = true;
    this.startX = e.offsetX;
    this.startY = e.offsetY;
    // pen
    this.lastX = e.offsetX;
    this.lastY = e.offsetY;

    const ctx = this.getCtxFor(this.activeTool);

    if (
      this.activeTool &&
      [ETools.line, ETools.rectangle, ETools.circle, ETools.arrow].includes(
        this.activeTool
      )
    ) {
      // this.snapshot = this.ctx.getSvg().querySelector('g')?.cloneNode(true) as SVGElement;
      // this.snapshot = this.ctx.getImageData(
      //   0,
      //   0,
      //   this.canvas.width,
      //   this.canvas.height
      // );
    }
    if (ETools.pen === this.activeTool) {
      ctx.beginPath();
      ctx.moveTo(this.lastX, this.lastY);
      this.activeDrawing = new Drawing(ctx, this.activeTool, {
        color: ctx.strokeStyle,
        size: ctx.lineWidth,
        points: [{ x: this.lastX / s, y: this.lastY / s }],
      });
      this.activeDrawing.prepare();
    }
    if (ETools.eraser === this.activeTool) {
      this.eraseAtPosition(this.lastX, this.lastY);
    }
    if (ETools.text === this.activeTool) {
      if (this.isExistedTextActived) {
        this.makeTextInputBlur();
        this.isExistedTextActived = false;
      }
      const clickedText = this.textHistory.find(text =>
        text.contains(this.startX / s, this.startY / s)
      );
      if (clickedText) {
        this.textMaker.style.setProperty('display', 'block');
        const x =
          clickedText.x + this.textMaker.offsetWidth / 2 - 10;
        const y = clickedText.y + 3;
        this.isExistedTextActived = true;
        this.textMaker.style.setProperty('left', `${x}px`);
        this.textMaker.style.setProperty('top', `${y}px`);

        this.makeTextInputFocus();
        this.textValue = clickedText.content;
        this.activeDrawingText = clickedText;
        return;
      }

      if (!this.getIsDrawingTextReady()) {
        this.textMaker.style.setProperty('display', 'block');
        const x =
          this.startX + this.textMaker.offsetWidth / 2 - 10;
        const y = this.startY + 3;
        this.textMaker.style.setProperty('left', `${x}px`);
        this.textMaker.style.setProperty('top', `${y}px`);

        this.makeTextInputFocus();
        this.isDrawing = false;
        this.activeDrawingText = new DrawText(
          this.ctx,
          this.startX / s,
          this.startY / s,
          '',
          this.ctx.strokeStyle as string,
          // this.ctx.lineWidth
          4
        );
      } else {
        this.makeTextInputBlur();
      }
    }
  }

() => {
    if (this.activeDrawingText && this.textValue.trim()) {
      this.activeDrawingText.content = this.textValue;
      if (!this.textHistory.includes(this.activeDrawingText)) {
        this.textHistory = [...this.textHistory, this.activeDrawingText];

        const textDrawing = new Drawing(this.ctx, ETools.text, {
          color: this.activeDrawingText.color,
          size: this.activeDrawingText.size,
          content: this.activeDrawingText.content,
          x: this.activeDrawingText.x,
          y: this.activeDrawingText.y,
        });
        textDrawing.id = this.activeDrawingText.id;
        this.history = [...this.history, textDrawing];
      }
      this.refreshCanvas();
    }
    if (this.isExistedTextActived) {
    } else {
      this.hideTextMaker();
      this.resetDrawingTextState();
    }
  }

(e: PointerEvent) => {
    const s = this.scale;
    const currentX = e.offsetX;
    const currentY = e.offsetY;
    this.updateEraser(e.offsetX, e.offsetY);
    if (!this.isDrawing) {
      return;
    }
    const ctx = this.getCtxFor(this.activeTool);
    switch (this.activeTool) {
      case ETools.pen:
      case ETools.highlightRect:
        ctx.lineTo(currentX, currentY);
        ctx.stroke();
        if (this.activeDrawing) {
          this.activeDrawing.data.points.push({ x: currentX / s, y: currentY / s });
        }
        break;
      case ETools.eraser:
        this.eraseAlongPath(this.lastX / s, this.lastY / s, currentX / s, currentY / s);
        this.lastX = currentX;
        this.lastY = currentY;
        break;
      case ETools.line:
      case ETools.rectangle:
      case ETools.circle:
      case ETools.arrow:
        if (this._lastSvgGrp) {
          this._lastSvgGrp.remove();
          this._lastSvgGrp = undefined;
          // ctx.getSvg().replaceChildren(this.snapshot);
          // ctx.__groupStack = [this.snapshot as SVGGElement];
          // ctx.__currentElement = this.snapshot as SVGElement;
        }
        ctx.save();
        // ctx.putImageData?.(this.snapshot, 0, 0);
        ctx.beginPath();
        if (this.activeTool === ETools.line) {
          ctx.moveTo(this.startX, this.startY);
          ctx.lineTo(currentX, currentY);
          ctx.stroke();
          this.activeDrawing = new Drawing(ctx, ETools.line, {
            color: ctx.strokeStyle,
            size: ctx.lineWidth,
            startX: this.startX / s,
            startY: this.startY / s,
            endX: currentX / s,
            endY: currentY / s,
          });
        }
        if (this.activeTool === ETools.rectangle) {
          const width = Math.abs(currentX - this.startX);
          const height = Math.abs(currentY - this.startY);
          ctx.strokeRect(
            Math.min(this.startX, currentX),
            Math.min(this.startY, currentY),
            width,
            height
          );
          this.activeDrawing = new Drawing(ctx, ETools.rectangle, {
            color: ctx.strokeStyle,
            size: ctx.lineWidth,
            startX: Math.min(this.startX, currentX) / s,
            startY: Math.min(this.startY, currentY) / s,
            endX: Math.max(this.startX, currentX) / s,
            endY: Math.max(this.startY, currentY) / s,
          });
        }
        if (this.activeTool === ETools.arrow) {
          this.drawArrow(this.startX, this.startY, currentX, currentY);
          this.activeDrawing = new Drawing(ctx, ETools.arrow, {
            color: ctx.strokeStyle,
            size: ctx.lineWidth,
            startX: this.startX / s,
            startY: this.startY / s,
            endX: currentX / s,
            endY: currentY / s,
          });
        }
        if (this.activeTool === ETools.circle) {
          const radius = Math.sqrt(
            Math.pow(currentX - this.startX, 2) +
              Math.pow(currentY - this.startY, 2)
          );
          ctx.arc(this.startX, this.startY, radius, 0, Math.PI * 2);
          ctx.stroke();
          this.activeDrawing = new Drawing(ctx, ETools.circle, {
            color: ctx.strokeStyle,
            size: ctx.lineWidth,
            startX: this.startX / s,
            startY: this.startY / s,
            endX: currentX / s,
            endY: currentY / s,
          });
        }
        ctx.closePath();
        const g = (ctx as any).__closestGroupOrSvg() as SVGElement;
        if (g?.tagName === 'g') this._lastSvgGrp = g;
        ctx.restore();
        break;
    }
  }

() => {
    this.isDrawing = false;
    const ctx = this.getCtxFor(this.activeTool);
    if (ETools.pen === this.activeTool) {
      ctx.closePath();
      if (this.activeDrawing && this.activeDrawing.data.points.length > 1) {
        this.history = [...this.history, this.activeDrawing];
      }
      this.activeDrawing?.postCleanup?.();
      this.activeDrawing = undefined;
    }
    if (
      this.activeTool &&
      [ETools.arrow, ETools.circle, ETools.line, ETools.rectangle].includes(
        this.activeTool
      )
    ) {
      if (this.activeDrawing) {
        this.history = [...this.history, this.activeDrawing];
      }
      this.activeDrawing?.postCleanup?.();
      this.activeDrawing = undefined;
    }
    this._lastSvgGrp = undefined;
  }

(value: StyleBase<any>) => {
    this.emit('scriber-toolbar', {
      detail: {
        type: 'tool-style-change',
        info: {
          value,
        },
      },
    });

    if (value instanceof Color) {
      this.activeColor =
        value.configurations.get(ETools.pen) ?? value.getDefaultValue();
    }
    if (value instanceof Thickness) {
      this.activeThickness =
        value.configurations.get(ETools.pen) ?? value.getDefaultValue();
    }
    if (value instanceof Size) {
      this.activeSize =
        value.configurations.get(ETools.pen) ?? value.getDefaultValue();
    }
  }

(e: Event) => {
    const paths = e.composedPath() as HTMLElement[];
    const hasColorTooltip = paths.some(path => {
      return path.id === SETTING_IDS.color;
    });
    const hasThicknessTooltip = paths.some(path => {
      return path.id === SETTING_IDS.thickness;
    });
    const hasShapeTooltip = paths.some(path => {
      return path.id === SETTING_IDS.shape;
    });
    const hasSizeTooltip = paths.some(path => {
      return path.id === SETTING_IDS.size;
    });
    if (!hasColorTooltip) {
      this.toggleState('showColorSetting', false);
    }
    if (!hasShapeTooltip) {
      this.toggleState('showShapeSetting', false);
    }
    if (!hasThicknessTooltip) {
      this.toggleState('showThicknessSetting', false);
    }
    if (!hasSizeTooltip) {
      this.toggleState('showSizeSetting', false);
    }
  }
